package com.example.order;

import com.example.order.client.*; import com.example.order.dto.*; import com.example.order.entity.*; import com.example.order.exception.ApiException; import com.example.order.repository.OrderRepository; import com.example.order.service.OrderService; import com.example.order.soap.ProcessPaymentResponse; import java.math.*; import java.util.*; import static org.junit.jupiter.api.Assertions.*; import static org.mockito.ArgumentMatchers.*; import static org.mockito.Mockito.*; import org.junit.jupiter.api.Test; import org.springframework.http.HttpStatus; import org.springframework.web.client.HttpClientErrorException; import org.springframework.ws.client.WebServiceIOException;

/** Focused orchestration tests using mocked downstream services. */
class OrderServiceTest {
  private final ProductClient products=mock(ProductClient.class); private final PaymentClient payments=mock(PaymentClient.class); private final OrderRepository repository=mock(OrderRepository.class); private final OrderService service=new OrderService(products,payments,repository);
  private OrderRequest request(){return request(List.of(new OrderRequest.Item(1L,2)));}
  private OrderRequest request(List<OrderRequest.Item> items){return new OrderRequest("Asha",items,new OrderRequest.Payment("CARD","4111111111111111"));}
  @Test void happyPathConfirmsAndReserves(){when(products.get(1)).thenReturn(new ProductView(1L,"Mouse","accessories",BigDecimal.TEN,5));doNothing().when(products).reserve(1,2);var response=new ProcessPaymentResponse();response.setStatus("APPROVED");response.setTransactionId("TXN-1");when(payments.process(anyString(),any(),anyString(),anyString())).thenReturn(response);when(repository.save(any())).thenAnswer(i->i.getArgument(0));assertEquals("CONFIRMED",service.place(request()).getStatus());verify(products).reserve(1,2);}
  @Test void declinedReleasesStock(){when(products.get(1)).thenReturn(new ProductView(1L,"Mouse","accessories",BigDecimal.TEN,5));var response=new ProcessPaymentResponse();response.setStatus("DECLINED");response.setMessage("Card declined by issuer");when(payments.process(anyString(),any(),anyString(),anyString())).thenReturn(response);when(repository.save(any())).thenAnswer(i->i.getArgument(0));assertEquals("PAYMENT_FAILED",service.place(request()).getStatus());verify(products).release(1,2);}
  @Test void laptopStandOutOfStockReturns409AndReleasesEarlierReservations(){var items=List.of(new OrderRequest.Item(1L,2),new OrderRequest.Item(5L,1));when(products.get(1)).thenReturn(new ProductView(1L,"Mouse","accessories",BigDecimal.TEN,5));when(products.get(5)).thenReturn(new ProductView(5L,"Laptop Stand","accessories",BigDecimal.TEN,0));doNothing().when(products).reserve(1,2);doThrow(HttpClientErrorException.Conflict.create(HttpStatus.CONFLICT,"conflict",null,null,null)).when(products).reserve(5,1);ApiException error=assertThrows(ApiException.class,()->service.place(request(items)));assertEquals(409,error.getStatus());verify(products).release(1,2);}
  @Test void paymentUnavailableReleasesStock(){when(products.get(1)).thenReturn(new ProductView(1L,"Mouse","accessories",BigDecimal.TEN,5));doThrow(new WebServiceIOException("down")).when(payments).process(anyString(),any(),anyString(),anyString());when(repository.save(any())).thenAnswer(i->i.getArgument(0));ApiException error=assertThrows(ApiException.class,()->service.place(request()));assertEquals(503,error.getStatus());verify(products).release(1,2);}
  @Test void cancelRefundsAndReleasesStock(){var order=new Order("ORD-1","Asha",BigDecimal.TEN,"CONFIRMED","1111");order.setTransactionId("TXN-1");order.getItems().add(new OrderItem(1L,"Mouse",BigDecimal.TEN,2,BigDecimal.valueOf(20)));when(repository.findById("ORD-1")).thenReturn(Optional.of(order));when(repository.save(order)).thenReturn(order);Order cancelled=service.cancel("ORD-1");assertEquals("CANCELLED",cancelled.getStatus());verify(payments).refund("TXN-1");verify(products).release(1,2);}
}
